import React, { useId } from 'react';
import { Dialog, DialogContent, DialogTitle } from '@mui/material';
import GameIconButton from './GameIconButton';
import PlayArrowOutlinedIcon from '@mui/icons-material/PlayArrowOutlined';
import CloseIcon from '@mui/icons-material/Close';
import { useTheme } from '@mui/material/styles';
import { GameCopy } from './gameCopy';

export default function GameHelpDialog({
  open,
  onClose,
  onStart,
  t,
  game,
  children,
}: {
  open: boolean;
  onClose: () => void;
  onStart?: () => void;
  t: GameCopy;
  game: 'wordle' | 'blank' | 'flashcards';
  children?: React.ReactNode;
}) {
  const title = useId();
  const theme = useTheme();
  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth aria-labelledby={title}>
      <DialogTitle id={title} sx={{ pr: 7, fontSize: '1.15rem' }}>
        {t.howToPlay} · {t[game]}
      </DialogTitle>
      <span className="game-dialog-close">
        <GameIconButton label={t.close} onClick={onClose}>
          <CloseIcon />
        </GameIconButton>
      </span>
      <DialogContent className="games-page game-dialog" data-theme={theme.palette.mode}>
        <p>
          {game === 'wordle' ? t.englishHelp : game === 'blank' ? t.blankHelp : t.flashcardsHelp}
        </p>
        {children}
        <p className="game-hint">{t.timerHelp}</p>
        {onStart && (
          <div className="game-actions">
            <button className="game-action game-primary" onClick={onStart}>
              <PlayArrowOutlinedIcon aria-hidden="true" />
              {t.start}
            </button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}
