import React, { useEffect, useRef, useState } from 'react';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import ReplayIcon from '@mui/icons-material/Replay';
import PlayArrowOutlinedIcon from '@mui/icons-material/PlayArrowOutlined';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import RestartAltIcon from '@mui/icons-material/RestartAlt';
import GameIconButton from './GameIconButton';
import GameConfetti from './GameConfetti';
import GameHelpDialog from './GameHelpDialog';
import GameStopwatch from './GameStopwatch';
import { gameReferences } from './catalog';
import { gameCopy } from './gameCopy';
import { loadGameVerses } from './gameData';
import {
  answerQuestion,
  buildDeck,
  missedQuestions,
  newRound,
  nextQuestion,
  QuizRound,
  quizScore,
  restoreQuiz,
} from './quizEngine';
import { QuizMode } from './types';
import { readGameStorage, writeGameStorage } from './storage';

export default function VerseGame({
  translation,
  kind,
  settings,
  active = true,
}: {
  translation: string;
  kind: 'blank' | 'flashcards';
  settings?: React.ReactNode;
  active?: boolean;
}) {
  const { t, locale, bookName } = gameCopy(translation);
  const [mode, setMode] = useState<QuizMode>(kind === 'blank' ? 'blank' : 'easy');
  const [burst, setBurst] = useState(0);
  const [round, setRound] = useState<QuizRound | null>(null);
  const [status, setStatus] = useState<'setup' | 'loading' | 'error' | 'insufficient'>('setup');
  const [storageError, setStorageError] = useState(false);
  const request = useRef<AbortController | null>(null);
  const key = `revelationary.quiz.v1.${translation}.${mode}`;
  const saved = restoreQuiz(readGameStorage(key), translation, mode);
  const [helpOpen, setHelpOpen] = useState(() => !saved);
  useEffect(() => () => request.current?.abort(), []);
  useEffect(() => {
    if (round) {
      setStorageError(!writeGameStorage(key, round));
    }
  }, [key, round]);
  const start = async () => {
    request.current?.abort();
    const controller = new AbortController();
    request.current = controller;
    setHelpOpen(false);
    setStatus('loading');
    setRound(null);
    try {
      const pool = await loadGameVerses(translation, gameReferences, controller.signal);
      if (controller.signal.aborted) {
        return;
      }
      const deck = buildDeck(pool, mode, bookName, locale);
      if (deck.length < 10) {
        setStatus('insufficient');
        return;
      }
      setRound(newRound(deck, translation, mode));
      setStatus('setup');
    } catch {
      if (!controller.signal.aborted) {
        setStatus('error');
      }
    }
  };
  const reset = () => {
    request.current?.abort();
    setRound(null);
    setStatus('setup');
    setHelpOpen(true);
  };
  const difficulty = kind === 'flashcards' && (
    <label>
      {t.difficulty}
      <select
        value={mode}
        disabled={status === 'loading'}
        onChange={(e) => setMode(e.target.value as QuizMode)}
      >
        <option value="easy">{t.easy}</option>
        <option value="medium">{t.medium}</option>
        <option value="hard">{t.hard}</option>
      </select>
    </label>
  );
  const help = (
    <GameHelpDialog
      open={helpOpen && active}
      onClose={() => setHelpOpen(false)}
      onStart={!round && status !== 'loading' ? () => void start() : undefined}
      t={t}
      game={kind}
    >
      {!round && settings}
      {!round && difficulty}
      {kind === 'flashcards' && <p>{t[`${mode === 'blank' ? 'easy' : mode}Help`]}</p>}
    </GameHelpDialog>
  );
  if (!round) {
    return (
      <div className="game-panel">
        {help}
        <div className="game-toolbar game-toolbar-end">
          <GameIconButton label={t.howToPlay} onClick={() => setHelpOpen(true)}>
            <InfoOutlinedIcon />
          </GameIconButton>
        </div>
        {difficulty}
        {mode !== 'blank' && <p>{t[`${mode}Help`]}</p>}
        {status === 'loading' ? (
          <p role="status">{t.loading}</p>
        ) : (
          <>
            {status !== 'setup' && (
              <p role="alert">{status === 'error' ? t.unavailable : t.insufficient}</p>
            )}
            <div className="game-actions">
              {status === 'setup' ? (
                <button className="game-action" onClick={() => setHelpOpen(true)}>
                  <PlayArrowOutlinedIcon aria-hidden="true" />
                  {t.start}
                </button>
              ) : (
                <GameIconButton label={t.retry} onClick={() => void start()}>
                  <ReplayIcon />
                </GameIconButton>
              )}
              {saved && (
                <button className="game-action" onClick={() => setRound(saved)}>
                  <PlayArrowOutlinedIcon aria-hidden="true" />
                  {t.resume}
                </button>
              )}
            </div>
          </>
        )}
      </div>
    );
  }
  const done = round.index >= round.questions.length;
  const question = round.questions[round.index];
  const answer = round.answers[round.index];
  return (
    <div className="game-panel">
      <GameConfetti burst={burst} />
      {help}
      <div className="game-toolbar">
        <GameStopwatch label={t.time} startedAt={round.startedAt} finishedAt={round.finishedAt} />
        <GameIconButton label={t.howToPlay} onClick={() => setHelpOpen(true)}>
          <InfoOutlinedIcon />
        </GameIconButton>
      </div>
      {storageError && <p role="status">{t.storage}</p>}
      {done ? (
        <>
          <h2>{t.results}</h2>
          <p className="game-score">
            {t.score}: {quizScore(round)}/{round.questions.length}
          </p>
          <div className="game-actions">
            {missedQuestions(round).length > 0 && (
              <button
                className="game-action"
                onClick={() => setRound(newRound(missedQuestions(round), translation, mode))}
              >
                <ReplayIcon aria-hidden="true" />
                {t.review}
              </button>
            )}
            <button className="game-action" onClick={reset}>
              <RestartAltIcon aria-hidden="true" />
              {t.newRound}
            </button>
          </div>
        </>
      ) : (
        <>
          <div className="game-progress">
            <span>
              {t.progress} {round.index + 1}/{round.questions.length}
            </span>
            <span>
              {t.score}: {quizScore(round)}
            </span>
          </div>
          <progress aria-label={t.progress} value={round.index} max={round.questions.length} />
          {question.hint && <p className="game-hint">{question.hint}</p>}
          <h2 className="game-verse" lang={locale}>
            {question.prompt}
          </h2>
          <div className="game-choices">
            {question.choices.map((choice, i) => (
              <button
                key={choice.id}
                disabled={answer !== null}
                data-result={
                  answer === null
                    ? undefined
                    : choice.id === question.answerId
                      ? 'correct'
                      : choice.id === answer
                        ? 'incorrect'
                        : undefined
                }
                onClick={() =>
                  setRound((current) => (current ? answerQuestion(current, choice.id) : current))
                }
              >
                <span aria-hidden="true">{i + 1}</span>
                {choice.label}
              </button>
            ))}
          </div>
          {answer !== null && (
            <div className="game-reveal" role="status">
              <p>
                {answer === question.answerId
                  ? t.correct
                  : `${t.incorrect} ${question.choices.find((c) => c.id === question.answerId)?.label}`}
              </p>
              <button
                className="game-action"
                onClick={() => {
                  const next = nextQuestion(round);
                  if (
                    next.index === next.questions.length &&
                    round.index < round.questions.length
                  ) {
                    setBurst((n) => n + 1);
                  }
                  setRound(next);
                }}
              >
                {t.next}
                <ArrowForwardIcon aria-hidden="true" />
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
