import React, { useEffect, useState } from 'react';

/** Event-driven: mounting a restored result must never replay its celebration. */
export default function GameConfetti({ burst }: { burst: number }) {
  const [active, setActive] = useState(false);
  useEffect(() => {
    const motion = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    if (!burst || motion?.matches) {
      return;
    }
    setActive(true);
    const stop = () => setActive(false);
    const timer = setTimeout(stop, 2000);
    motion?.addEventListener?.('change', stop);
    return () => {
      clearTimeout(timer);
      motion?.removeEventListener?.('change', stop);
    };
  }, [burst]);
  if (!active) {
    return null;
  }
  return (
    <div key={burst} className="game-confetti" aria-hidden="true" data-testid="game-confetti">
      {Array.from({ length: 36 }, (_, i) => (
        <i
          key={i}
          style={
            {
              left: `${(i * 37) % 100}%`,
              animationDelay: `${(i % 6) * 45}ms`,
              '--confetti-drift': `${((i * 41) % 180) - 90}px`,
              '--confetti-turn': `${(i % 2 ? 1 : -1) * (240 + i * 17)}deg`,
              backgroundColor: ['#bda05e', '#66886d', '#718fa5', '#b28176'][i % 4],
            } as React.CSSProperties
          }
        />
      ))}
    </div>
  );
}
