import { translationToBibleFolder } from '../services/bibleSearchService';
import { VerseReference } from './types';

export const gameTranslations = [
  { id: 'kjv', name: 'King James Version (KJV)', locale: 'en' },
  { id: 'fbv', name: 'Free Bible Version (FBV)', locale: 'en' },
  { id: 'cuv', name: '和合本 (CUV)', locale: 'zh-hans' },
  { id: 'lut', name: 'Lutherbibel (LUT)', locale: 'de' },
  { id: 'es-rv09', name: 'Reina Valera 1909', locale: 'es' },
  { id: 'it-db1885', name: 'Diodati 1885', locale: 'it' },
  { id: 'cs-bkr', name: 'Bible kralická', locale: 'cs' },
  { id: 'sv-skb', name: 'Svenska Bibeln', locale: 'sv' },
  { id: 'id-tsi', name: 'Alkitab Indonesia', locale: 'id' },
  { id: 'nl-nld1939', name: 'Nederlandse Bijbel 1939', locale: 'nl' },
  { id: 'vi-ovcb', name: 'Kinh Thánh Việt', locale: 'vi' },
] as const;

export const isGameTranslation = (value: unknown): value is string =>
  typeof value === 'string' &&
  gameTranslations.some((item) => item.id === value) &&
  Object.prototype.hasOwnProperty.call(translationToBibleFolder, value);

export function defaultGameTranslation(saved?: string, reader?: string, language = 'en'): string {
  if (isGameTranslation(saved)) {
    return saved;
  }
  if (isGameTranslation(reader)) {
    return reader;
  }
  const prefix = language.toLowerCase().split('-')[0];
  return gameTranslations.find((item) => item.locale.split('-')[0] === prefix)?.id || 'kjv';
}

// References only: verse wording always comes from the selected Bible source.
const chapters: Array<[string, number, number[]]> = [
  ['genesis', 1, [1, 3, 27]],
  ['psalms', 23, [1, 4, 6]],
  ['psalms', 119, [11, 105]],
  ['proverbs', 3, [5, 6, 7]],
  ['isaiah', 40, [8, 31]],
  ['matthew', 5, [9, 14, 16]],
  ['matthew', 6, [21, 33, 34]],
  ['john', 1, [1, 5, 14]],
  ['john', 3, [16, 17, 21]],
  ['john', 14, [6, 15, 27]],
  ['romans', 8, [1, 28, 31]],
  ['romans', 12, [2, 12, 21]],
  ['firstCorinthians', 13, [4, 7, 13]],
  ['philippians', 4, [4, 6, 13, 19]],
  ['firstJohn', 4, [7, 8, 19]],
];
export const gameReferences: VerseReference[] = chapters.flatMap(([book, chapter, verses]) =>
  verses.map((verse) => ({ book, chapter, verse })),
);
