import { bibleBookChapterCounts } from '../data/bibleBookChapters';
import { translationToBibleFolder } from '../services/bibleSearchService';
import { cleanVerseText, stripFbvCommentary } from '../utils/bibleTextUtils';
import { isGameTranslation } from './catalog';
import { GameVerse, VerseReference, verseKey } from './types';

const chapterCache = new Map<string, GameVerse[]>();
const canonicalBooks = Object.keys(bibleBookChapterCounts);

/** Validate actual returned references. Never relabel a different book/chapter. */
export function parseGameChapter(
  data: unknown,
  book: string,
  chapter: number,
  translation: string,
): GameVerse[] {
  if (!Array.isArray(data)) {
    return [];
  }
  const seen = new Set<string>();
  const ambiguous = new Set<string>();
  const parsed = data.flatMap((item): GameVerse[] => {
    if (
      !item ||
      typeof item !== 'object' ||
      typeof item.book !== 'string' ||
      item.book.trim().toLowerCase() !== book.toLowerCase() ||
      Number(item.chapter) !== chapter ||
      !Number.isInteger(Number(item.verse)) ||
      Number(item.verse) < 1 ||
      typeof item.text !== 'string'
    ) {
      return [];
    }
    const text = cleanVerseText(
      translation === 'fbv'
        ? stripFbvCommentary(item.text, String(chapter), String(item.verse))
        : item.text,
      translation,
    )
      .replace(/\s+/g, ' ')
      .trim();
    const verse = { book, chapter, verse: Number(item.verse), text, translation };
    const key = verseKey(verse);
    if (seen.has(key)) {
      ambiguous.add(key);
    }
    if (seen.has(key) || text.length < 8 || text.length > 900 || /<[^>]*>/.test(text)) {
      return [];
    }
    seen.add(key);
    return [verse];
  });
  return parsed.filter((verse) => !ambiguous.has(verseKey(verse)));
}

export async function loadGameVerses(
  translation: string,
  references: VerseReference[],
  signal: AbortSignal,
): Promise<GameVerse[]> {
  if (!isGameTranslation(translation) || references.length > 80) {
    throw new Error('Unsupported game selection');
  }
  const unique = new Map<string, VerseReference>();
  for (const reference of references) {
    const { book, chapter, verse } = reference;
    if (
      !canonicalBooks.includes(book) ||
      !Number.isInteger(chapter) ||
      chapter < 1 ||
      chapter > bibleBookChapterCounts[book] ||
      !Number.isInteger(verse) ||
      verse < 1
    ) {
      throw new Error('Invalid game reference');
    }
    unique.set(`${book}:${chapter}`, reference);
  }
  const queue = [...unique.values()];
  const loaded: GameVerse[] = [];
  let cursor = 0;
  let failed = false;
  async function worker() {
    while (cursor < queue.length) {
      if (signal.aborted) {
        throw new DOMException('Cancelled', 'AbortError');
      }
      const { book, chapter } = queue[cursor++];
      const key = `${translation}:${book}:${chapter}`;
      let verses = chapterCache.get(key);
      if (!verses) {
        const controller = new AbortController();
        const abort = () => controller.abort();
        signal.addEventListener('abort', abort, { once: true });
        const timeout = setTimeout(abort, 12000);
        try {
          const response = await fetch(
            `https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/${translationToBibleFolder[translation]}/books/${book.toLowerCase()}/chapters/${chapter}.json`,
            { signal: controller.signal },
          );
          if (!response.ok) {
            throw new Error('Chapter unavailable');
          }
          verses = parseGameChapter(await response.json(), book, chapter, translation);
          if (signal.aborted) {
            throw new DOMException('Cancelled', 'AbortError');
          }
          if (verses.length) {
            // Bounded in-memory cache; no full-Bible downloads or account data.
            if (chapterCache.size >= 40) {
              const oldest = chapterCache.keys().next().value;
              if (oldest !== undefined) {
                chapterCache.delete(oldest);
              }
            }
            chapterCache.set(key, verses);
          }
        } catch (error) {
          if (signal.aborted) {
            throw error;
          }
          // Another chapter can still make a complete round. Do not cache failure.
          failed = true;
          verses = [];
        } finally {
          clearTimeout(timeout);
          signal.removeEventListener('abort', abort);
        }
      }
      loaded.push(...verses);
    }
  }
  await Promise.all(Array.from({ length: Math.min(4, queue.length) }, worker));
  if (signal.aborted) {
    throw new DOMException('Cancelled', 'AbortError');
  }
  if (!loaded.length && failed) {
    throw new Error('Verse sources are unavailable');
  }
  const requested = new Set(references.map(verseKey));
  return loaded.filter((verse) => requested.has(verseKey(verse)));
}
