import React, { useCallback, useEffect, useState } from 'react';
import { Tab, Tabs } from '@mui/material';
import { gamePath, resolveGameRoute } from '../public-site/routes';
import Cookies from 'js-cookie';
import { defaultGameTranslation, gameTranslations } from './catalog';
import { gameCopy } from './gameCopy';
import { readGameStorage, writeGameStorage } from './storage';
import VerseGame from './VerseGame';
import WordleGame from './WordleGame';
import { GameKind } from './types';

function initialTranslation() {
  let reader: string | undefined;
  try {
    reader = Cookies.get('translation') || localStorage.getItem('translation') || undefined;
  } catch {
    /* Use browser language. */
  }
  let saved: unknown;
  try {
    saved = JSON.parse(readGameStorage('revelationary.gameTranslation') || 'null');
  } catch {
    /* Old preference. */
  }
  return defaultGameTranslation(
    typeof saved === 'string' ? saved : undefined,
    reader,
    navigator.language,
  );
}
export default function GamesApp({
  initialGame,
  leaderboardView = false,
}: {
  initialGame: GameKind;
  leaderboardView?: boolean;
}) {
  const [showLeaderboard, setShowLeaderboard] = useState(leaderboardView);
  const [gameVisited, setGameVisited] = useState(!leaderboardView);
  const changeView = useCallback(
    (leaderboard: boolean) => {
      const path = gamePath(initialGame, leaderboard);
      if (`${window.location.pathname}${window.location.search}` !== path) {
        window.history.pushState(null, '', path);
      }
      setShowLeaderboard(leaderboard);
      if (!leaderboard) {
        setGameVisited(true);
      }
    },
    [initialGame],
  );
  useEffect(() => {
    const restoreView = () => {
      const route = resolveGameRoute(window.location.pathname, window.location.search);
      if (route?.kind === initialGame) {
        setShowLeaderboard(route.leaderboardView);
        if (!route.leaderboardView) {
          setGameVisited(true);
        }
      }
    };
    window.addEventListener('popstate', restoreView);
    return () => window.removeEventListener('popstate', restoreView);
  }, [initialGame]);
  const [translation, setTranslation] = useState(initialTranslation);
  const { t } = gameCopy(translation);
  const translationControl = (
    <label className="game-translation">
      {t.translation}
      <select
        value={translation}
        onChange={(e) => {
          setTranslation(e.target.value);
          writeGameStorage('revelationary.gameTranslation', e.target.value);
        }}
      >
        {gameTranslations.map((item) => (
          <option key={item.id} value={item.id}>
            {item.name}
          </option>
        ))}
      </select>
    </label>
  );
  return (
    <div className="games-app">
      <p className="game-back">
        <a href="/games/">← {t.allGames}</a>
      </p>
      <Tabs
        className="game-tabs"
        value={showLeaderboard ? 1 : 0}
        onChange={(_, value) => changeView(value === 1)}
        aria-label={t[initialGame]}
        variant="fullWidth"
        textColor="inherit"
        TabIndicatorProps={{ style: { backgroundColor: 'currentColor' } }}
      >
        <Tab disableRipple label={t.gameTab} id="game-tab" aria-controls="game-content" />
        <Tab
          disableRipple
          label={t.leaderboardTab}
          id="leaderboard-tab"
          aria-controls="leaderboard-content"
        />
      </Tabs>
      {!showLeaderboard && translationControl}
      {initialGame === 'wordle' ? (
        <WordleGame
          t={t}
          leaderboardView={showLeaderboard}
          onViewChange={changeView}
          settings={translationControl}
        />
      ) : (
        <>
          <div
            role="tabpanel"
            id="game-content"
            aria-labelledby="game-tab"
            hidden={showLeaderboard}
          >
            {gameVisited && (
              <VerseGame
                key={`${initialGame}:${translation}`}
                kind={initialGame}
                translation={translation}
                active={!showLeaderboard}
                settings={translationControl}
              />
            )}
          </div>
          <section
            className="game-panel"
            role="tabpanel"
            id="leaderboard-content"
            aria-labelledby="leaderboard-tab"
            hidden={!showLeaderboard}
          >
            <h2>{t.leaderboardTab}</h2>
            <p>{t.practiceLeaderboard}</p>
          </section>
        </>
      )}
    </div>
  );
}
